use std::collections::HashSet;

/// Removes duplicate values from the input vector, preserving the first
/// occurrence order of each element.  
///
/// Postconditions:
/// 1. The returned vector contains no duplicates.
/// 2. The set of elements in the returned vector is equal to the set of
///    elements in the input vector.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::with_capacity(nums.len());

    for x in nums {
        // `HashSet::insert` returns true if the value was not already present.
        if seen.insert(x) {
            result.push(x);
        }
    }

    result
}

